declarations.code:
template <class I>

concept weakly_incrementable =

    std::movable<I> &&

    requires(I i) {
        typename std::iter_difference_t<I>;

        requires /*is-signed-integer-like*/<std::iter_difference_t<I>>;

        { ++i } -> std::same_as<I &>; // not required to be equality-preserving

        i++; // not required to be equality-preserving
    };

examples.code:
#include <iterator>
#include <functional>
#include <cassert>
#include <iostream>

int main() {
    static_assert(std::weakly_incrementable<int *>);
    int values[]{3, 7};
    int *position = values;
    assert(*position == 3);
    ++position;
    assert(*position == 7);
    std::cout << "Checks passed\n";
}
